def _is_safe_public_ip(ip_str):
    import ipaddress as _ipa
    try:
        ip = _ipa.ip_address(ip_str)
    except ValueError:
        return False
    # Unwrap IPv4-mapped IPv6 (e.g. ::ffff:127.0.0.1) so the IPv4 checks apply.
    if isinstance(ip, _ipa.IPv6Address) and ip.ipv4_mapped is not None:
        ip = ip.ipv4_mapped
    # S1: salt deny-list yerine POZİTİF "küresel yönlendirilebilir" şartı.
    # Deny-list, CGNAT/paylaşımlı adres alanını (100.64.0.0/10, RFC 6598) ve
    # TEST-NET/benchmark (198.18.0.0/15, 192.0.0.0/24, ...) bloklarını KAÇIRIYORDU
    # (Py 3.11'de is_private bunları kapsamaz). is_global IANA kaydını izler;
    # eski deny-list, is_global semantiği Python sürümleri arasında oynadığı için
    # emniyet kemeri olarak korunur (iki katman da geçmeli).
    return ip.is_global and not (
        ip.is_private or ip.is_loopback or ip.is_link_local
        or ip.is_reserved or ip.is_multicast or ip.is_unspecified)


_ALLOWED_PORTS = {80, 443}


def _port_ok(parsed):
    """Açık port yalnızca 80/443 olabilir; varsayılan (None) kabul edilir.

    Adres kontrolü (_resolve_host_safely) IP'yi doğrular ama PORT'u doğrulamaz —
    saldırgan public-ama-iç bir IP'nin keyfi yüksek portuna (ör. :22, :6379,
    :5432) yönelterek iç servis taraması yapabilirdi. Bozuk port (.port ValueError)
    da reddedilir (SSRF sertleştirme)."""
    try:
        port = parsed.port
    except ValueError:
        return False
    return port is None or port in _ALLOWED_PORTS


def _resolve_host_safely(hostname):
    """Resolve hostname; raise ValueError if any address is non-public.

    Catches alternate IPv4 encodings (decimal/hex/short), IPv6 ULA/link-local,
    and hostnames that resolve to RFC1918/loopback. Returns list of resolved IPs.
    """
    import socket as _sock
    if not hostname:
        raise ValueError("Geçersiz URL.")
    try:
        infos = _sock.getaddrinfo(hostname, None)
    except _sock.gaierror:
        raise ValueError("Host adı çözümlenemedi.")
    ips = []
    for info in infos:
        ip = info[4][0]
        if not _is_safe_public_ip(ip):
            raise ValueError("İç ağ adresleri engellendi.")
        ips.append(ip)
    if not ips:
        raise ValueError("Host adı çözümlenemedi.")
    return ips


_MAX_FETCH_BYTES = 3_000_000  # ~3 MB


_dns_pin_lock = threading.Lock()


@contextlib.contextmanager
def _pin_getaddrinfo(hostname, ip):
    """Force socket.getaddrinfo to return `ip` for `hostname` while active.

    Closes the DNS-rebinding window in the SSRF guard: the socket connects to
    the exact IP that _resolve_host_safely already vetted, not a fresh (and
    attacker-flippable) lookup at connect time. The hostname is still used for
    TLS SNI and certificate validation, so HTTPS integrity is preserved.

    The patch is process-global, so it is serialized by a lock. Menu scraping
    is an infrequent, heavy operation, so serializing it is not a bottleneck;
    the lock is only held for connection setup, not for the body download.
    """
    import socket as _s
    family = _s.AF_INET6 if ":" in ip else _s.AF_INET
    with _dns_pin_lock:
        original = _s.getaddrinfo

        def _patched(host, port, *args, **kwargs):
            if host == hostname:
                return [(family, _s.SOCK_STREAM, 6, "", (ip, port))]
            return original(host, port, *args, **kwargs)

        _s.getaddrinfo = _patched
        try:
            yield
        finally:
            _s.getaddrinfo = original


def _safe_requests_get(url, *, timeout, headers=None, cookies=None,
                       max_redirects=5, max_bytes=None):
    """SSRF-safe GET for the WordPress REST fallback and the Google Drive
    downloader.

    These two paths previously used a bare requests.get with allow_redirects=True
    and no host validation, which bypassed the protections in _fetch_page. This
    helper mirrors those protections: it re-validates the host of EVERY hop with
    _resolve_host_safely (rejecting RFC1918/loopback/link-local/etc.), PINS the
    vetted IP for the socket connect to close the DNS-rebinding TOCTOU window,
    and follows redirects MANUALLY (allow_redirects=False) so an attacker who
    controls a Location header can't smuggle the request to an internal target.
    When max_bytes is given the body is materialised behind a hard size cap so
    later .content/.json()/.text reads are bounded.

    Returns the final streamed Response. Raises ValueError on a blocked host or
    an oversized body, and requests.exceptions.TooManyRedirects past the limit.
    """
    import requests as http_req
    from urllib.parse import urlparse, urljoin

    current = url
    for _ in range(max_redirects + 1):
        p = urlparse(current)
        if p.scheme not in ("http", "https") or not p.hostname:
            raise http_req.exceptions.InvalidURL("Geçersiz URL.")
        if not _port_ok(p):
            raise ValueError("Yalnızca 80/443 portlarına izin verilir.")
        safe_ips = _resolve_host_safely(p.hostname)  # ValueError if non-public
        with _pin_getaddrinfo(p.hostname, safe_ips[0]):
            r = http_req.get(current, timeout=timeout, stream=True,
                             allow_redirects=False, headers=headers, cookies=cookies)
        if r.status_code in (301, 302, 303, 307, 308):
            loc = r.headers.get("Location")
            # B20: 3xx ama Location varsa gövdeyi bırakıp sıradaki hop'a geç;
            # Location YOKSA takip edilemez → ham/kapalı streamed response'u
            # cap'siz döndürme, aşağıdaki cap'li okuma yoluna düş.
            if loc:
                r.close()  # release the unread streamed body before the next hop
                current = urljoin(current, loc)
                continue
        if max_bytes is not None:
            total = 0
            chunks = []
            for chunk in r.iter_content(8192):
                if not chunk:
                    continue
                chunks.append(chunk)
                total += len(chunk)
                if total > max_bytes:
                    r.close()
                    raise ValueError("İçerik çok büyük (boyut limiti aşıldı).")
            r._content = b"".join(chunks)
            r._content_consumed = True
        return r
    raise http_req.exceptions.TooManyRedirects("Çok fazla yönlendirme.")


def _validate_menu_url(url):
    from urllib.parse import urlparse, urlunparse, parse_qs, urlencode
    import re as _re

    url = url.strip()
    if not url:
        return None, None, "URL gerekli."

    if not _re.match(r'^https?://', url, _re.IGNORECASE):
        if _re.match(r'^[a-zA-Z0-9]', url):
            url = "https://" + url
        else:
            return None, None, "Geçersiz URL formatı."

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return None, None, "Yalnızca HTTP/HTTPS desteklenir."
    if not parsed.hostname:
        return None, None, "Geçersiz URL."
    if not _port_ok(parsed):
        return None, None, "Yalnızca 80/443 portlarına izin verilir."

    try:
        _resolve_host_safely(parsed.hostname)
    except ValueError as e:
        return None, None, str(e)

    tracking_params = {"utm_source", "utm_medium", "utm_campaign", "utm_term",
                       "utm_content", "fbclid", "gclid", "ref", "source"}
    qs = parse_qs(parsed.query, keep_blank_values=False)
    cleaned_qs = {k: v for k, v in qs.items() if k.lower() not in tracking_params}
    clean_query = urlencode(cleaned_qs, doseq=True) if cleaned_qs else ""
    clean_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path,
                            parsed.params, clean_query, ""))
    return urlparse(clean_url), clean_url, None


_USER_AGENTS = [
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
    "Mozilla/5.0 (Macintosh; Intel Mac OS X 14_5) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Safari/605.1.15",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:126.0) Gecko/20100101 Firefox/126.0",
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36 Edg/124.0.0.0",
]


def _acceptable_encodings():
    """Accept-Encoding değerini, GERÇEKTEN açabildiğimiz içerik-kodlamalarından kur.

    urllib3 gzip/deflate'i şeffaf açar; brotli ("br") ise yalnızca `brotli` veya
    `brotlicffi` paketi kuruluysa açılabilir. Decoder olmadan "br" reklamı yapmak,
    brotli'yi tercih eden (Cloudflare arkasındaki çoğu TR restoran sitesi gibi)
    origin'lerin sıkıştırılmış gövdeyi geri vermesine yol açar — urllib3 onu
    açamaz, "HTML" ikili çöpe döner ve hiçbir menü öğesi çıkarılamaz. Bu yüzden
    "br"yi yalnızca decoder mevcutsa ilan ederiz; aksi halde gzip'e düşeriz."""
    encodings = ["gzip", "deflate"]
    try:
        import brotli  # noqa: F401
        encodings.append("br")
    except ImportError:
        try:
            import brotlicffi  # noqa: F401
            encodings.append("br")
        except ImportError:
            pass
    return ", ".join(encodings)


_ACCEPT_ENCODING = _acceptable_encodings()


def _fetch_page(url, timeout=10):
    import requests as http_req
    import random
    from urllib.parse import urlparse, urljoin

    ua = random.choice(_USER_AGENTS)
    parsed = urlparse(url)
    headers = {
        "User-Agent": ua,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
        "Accept-Language": "tr-TR,tr;q=0.9,en-US;q=0.8,en;q=0.7",
        "Accept-Encoding": _ACCEPT_ENCODING,
        "DNT": "1",
        "Connection": "keep-alive",
        "Upgrade-Insecure-Requests": "1",
        "Referer": f"{parsed.scheme}://{parsed.hostname}/",
        "Sec-Fetch-Dest": "document",
        "Sec-Fetch-Mode": "navigate",
        "Sec-Fetch-Site": "same-origin",
        "Sec-Fetch-User": "?1",
    }

    session = http_req.Session()
    session.headers.update(headers)

    def _read_capped(resp):
        # Stream the body with a hard size cap so a malicious/oversized origin
        # can't exhaust memory. Materialise into resp._content so later reads
        # of resp.text behave normally.
        total = 0
        chunks = []
        for chunk in resp.iter_content(8192):
            if not chunk:
                continue
            chunks.append(chunk)
            total += len(chunk)
            if total > _MAX_FETCH_BYTES:
                resp.close()
                raise ValueError("Sayfa çok büyük (boyut limiti aşıldı).")
        resp._content = b"".join(chunks)
        resp._content_consumed = True
        return resp

    def _safe_get(target_url):
        # Re-validate every hop to defeat bypass via untrusted Location headers
        # from cooperative origins, then PIN the vetted IP for the actual socket
        # connection so the host can't be rebound to an internal address between
        # validation and connect (DNS-rebinding TOCTOU).
        p = urlparse(target_url)
        if p.scheme not in ("http", "https") or not p.hostname:
            raise http_req.exceptions.InvalidURL("Geçersiz URL.")
        if not _port_ok(p):
            raise ValueError("Yalnızca 80/443 portlarına izin verilir.")
        safe_ips = _resolve_host_safely(p.hostname)
        # stream=True so the TCP connect (which resolves DNS) happens inside the
        # pinned window; the body is downloaded later via _read_capped.
        with _pin_getaddrinfo(p.hostname, safe_ips[0]):
            return session.get(target_url, timeout=timeout,
                               allow_redirects=False, stream=True)

    def _follow(start_url):
        current = start_url
        for _ in range(5):
            r = _safe_get(current)
            if r.status_code in (301, 302, 303, 307, 308):
                loc = r.headers.get("Location")
                # B20: Location varsa sıradaki hop'a geç; yoksa takip edilemez →
                # ham streamed response'u cap'siz döndürmek yerine cap'li oku.
                if loc:
                    r.close()  # release the unread streamed body before next hop
                    current = urljoin(current, loc)
                    continue
                return _read_capped(r)
            return _read_capped(r)
        raise http_req.exceptions.TooManyRedirects("Çok fazla yönlendirme.")

    resp = _follow(url)

    if resp.status_code == 403 or (resp.status_code == 200 and len(resp.text) < 500):
        alt_ua = random.choice([u for u in _USER_AGENTS if u != ua] or _USER_AGENTS)
        session.headers["User-Agent"] = alt_ua
        import time
        time.sleep(random.uniform(0.3, 0.8))
        resp = _follow(url)

    resp.raise_for_status()
    return resp


def _is_google_drive_url(url):
    return bool(url) and ("drive.google.com" in url or "docs.google.com" in url)


def _extract_drive_file_id(url):
    import re
    patterns = [
        r'/file/d/([a-zA-Z0-9_-]+)',
        r'/document/d/([a-zA-Z0-9_-]+)',
        r'/spreadsheets/d/([a-zA-Z0-9_-]+)',
        r'/presentation/d/([a-zA-Z0-9_-]+)',
        r'[?&]id=([a-zA-Z0-9_-]+)',
        r'/open\?id=([a-zA-Z0-9_-]+)',
    ]
    for pat in patterns:
        m = re.search(pat, url)
        if m:
            return m.group(1)
    return None


def _get_drive_direct_url(url, file_id):
    if "docs.google.com/document" in url:
        return f"https://docs.google.com/document/d/{file_id}/export?format=txt", "doc"
    if "docs.google.com/spreadsheets" in url:
        return f"https://docs.google.com/spreadsheets/d/{file_id}/export?format=csv", "sheet"
    return f"https://drive.google.com/uc?export=download&id={file_id}", "file"


def _process_google_drive_url(url):
    import requests as http_req

    file_id = _extract_drive_file_id(url)
    if not file_id:
        return None, "Google Drive bağlantısından dosya kimliği çıkarılamadı."

    direct_url, url_type = _get_drive_direct_url(url, file_id)
    current_app.logger.debug(f"[DRIVE] Detected type={url_type}, file_id={file_id}, direct_url={direct_url}")

    _DRIVE_MAX_BYTES = 50 * 1024 * 1024

    try:
        # SSRF-safe: validates + pins every redirect hop (Google's export
        # endpoints redirect to googleusercontent.com, which resolves public).
        resp = _safe_requests_get(direct_url, timeout=30, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36",
        })
    except ValueError:
        return None, "Google Drive bağlantısı çözümlenemedi."
    except http_req.exceptions.Timeout:
        return None, "Google Drive dosyası indirilemedi — zaman aşımı."
    except http_req.exceptions.RequestException as e:
        return None, f"Google Drive bağlantı hatası: {type(e).__name__}"

    if resp.status_code in (403, 401):
        return None, json.dumps({
            "success": False,
            "error": "GOOGLE_DRIVE_LINK_RESTRICTED",
            "message": "Bu menü dosyası gizli olarak ayarlanmış. Lütfen Drive üzerinden dosya iznini 'Bağlantıya sahip olan herkes görüntüleyebilir' olarak değiştirip tekrar deneyin."
        })
    if resp.status_code == 404:
        return None, "Google Drive dosyası bulunamadı. Lütfen bağlantıyı kontrol edin."
    if resp.status_code != 200:
        return None, f"Google Drive hatası: HTTP {resp.status_code}"

    # B19: Content-Length sayısal olmayabilir (bozuk/uyumsuz sunucu); int()
    # ham ValueError'ı çağıranın koruması dışında patlatırdı. Güvenle ayrıştır;
    # ayrıştırılamıyorsa boyut kapısını atla (aşağıdaki streaming cap yine korur).
    content_length = resp.headers.get("Content-Length")
    declared_bytes = None
    if content_length:
        try:
            declared_bytes = int(content_length)
        except (TypeError, ValueError):
            declared_bytes = None
    if declared_bytes is not None and declared_bytes > _DRIVE_MAX_BYTES:
        resp.close()
        size_mb = declared_bytes // (1024 * 1024)
        return None, f"Dosya çok büyük ({size_mb}MB). Maksimum 50MB desteklenir. Lütfen dosyayı küçültüp tekrar deneyin."

    content_type = resp.headers.get("Content-Type", "").lower()
    chunks = []
    downloaded = 0
    for chunk in resp.iter_content(chunk_size=256 * 1024):
        downloaded += len(chunk)
        if downloaded > _DRIVE_MAX_BYTES:
            resp.close()
            return None, "Dosya çok büyük (maks 50MB). Lütfen dosyayı küçültüp tekrar deneyin."
        chunks.append(chunk)
    file_bytes = b"".join(chunks)

    current_app.logger.info(f"[DRIVE] Downloaded {len(file_bytes)} bytes, Content-Type: {content_type}")

    preview_lower = file_bytes[:5000].lower()
    is_drive_confirm = ("text/html" in content_type and
                        (b"virus scan" in preview_lower or b"download anyway" in preview_lower
                         or b"uc-download-link" in preview_lower or b"confirm=" in preview_lower))
    if is_drive_confirm:
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(file_bytes, "html.parser")
        confirm_link = soup.find("a", {"id": "uc-download-link"})
        if confirm_link and confirm_link.get("href"):
            confirm_url = "https://drive.google.com" + confirm_link["href"]
            current_app.logger.debug(f"[DRIVE] Virus scan confirmation redirect: {confirm_url}")
            try:
                resp2 = _safe_requests_get(confirm_url, timeout=15, headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                }, cookies=resp.cookies, max_bytes=_DRIVE_MAX_BYTES)
                if resp2.status_code == 200:
                    file_bytes = resp2.content
                    content_type = resp2.headers.get("Content-Type", "").lower()
                    current_app.logger.info(f"[DRIVE] Confirmed download: {len(file_bytes)} bytes, Content-Type: {content_type}")
            except Exception as e:
                current_app.logger.warning(f"[DRIVE] Confirm download failed: {e}")

    if "application/pdf" in content_type or file_bytes[:5] == b"%PDF-":
        current_app.logger.info(f"[DRIVE] Dispatching to PDF extractor")
        try:
            text = _extract_text_from_pdf(file_bytes)
            if text and len(text.strip()) > 20:
                text = _sanitize_menu_text(text)
                current_app.logger.info(f"[DRIVE] PDF extracted: {len(text)} chars")
                return {"title": "Google Drive PDF Menü", "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None
            return None, "PDF dosyasından menü metni çıkarılamadı."
        except ValueError as ve:
            msg = str(ve)
            if msg == "PDF_ENCRYPTED":
                return None, "Bu PDF şifre korumalıdır. Lütfen şifresiz bir PDF yükleyin."
            if msg == "PDF_CORRUPT":
                return None, "PDF dosyası bozuk veya okunamıyor. Lütfen farklı bir dosya deneyin."
            return None, f"PDF işlenirken hata: {msg}"
        except Exception as e:
            current_app.logger.warning(f"[DRIVE] PDF extraction failed: {type(e).__name__}: {e}")
            return None, f"PDF işlenirken hata: {type(e).__name__}"

    if "text/plain" in content_type or "text/csv" in content_type or url_type in ("doc", "sheet"):
        current_app.logger.info(f"[DRIVE] Dispatching as plain text")
        try:
            text = file_bytes.decode("utf-8", errors="replace")
        except Exception:
            text = file_bytes.decode("latin-1", errors="replace")
        if text and len(text.strip()) > 20:
            text = _sanitize_menu_text(text)
            current_app.logger.info(f"[DRIVE] Text extracted: {len(text)} chars")
            title = "Google Drive Doküman Menü" if url_type == "doc" else "Google Drive Menü"
            return {"title": title, "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None
        return None, "Dosyadan menü metni çıkarılamadı."

    if any(t in content_type for t in ("image/jpeg", "image/png", "image/webp", "image/gif")):
        current_app.logger.info(f"[DRIVE] Dispatching to Vision OCR")
        if len(file_bytes) > 10 * 1024 * 1024:
            return None, "Görsel dosya çok büyük (maks 10MB)."
        text = _extract_text_from_image(file_bytes, content_type)
        if text and len(text.strip()) > 20:
            text = _sanitize_menu_text(text)
            current_app.logger.info(f"[DRIVE] Vision OCR extracted: {len(text)} chars")
            return {"title": "Google Drive Görsel Menü", "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None
        return None, "Görselden menü metni okunamadı."

    if "text/html" in content_type:
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(file_bytes, "html.parser")
        for tag in soup(["script", "style", "link", "meta"]):
            tag.decompose()
        text = soup.get_text(separator="\n", strip=True)
        if text and len(text.strip()) > 20:
            text = _sanitize_menu_text(text)
            current_app.logger.info(f"[DRIVE] HTML fallback extracted: {len(text)} chars")
            return {"title": "Google Drive Menü", "body_text": text, "headings": [], "source_url": url, "menu_source": "google_drive"}, None

    return None, f"Desteklenmeyen dosya tipi: {content_type.split(';')[0]}"
